(()=>{
 'use strict';
 const rules=window.HUNTER_MAZE,key='shadow-hunter-maze-v1',$=id=>document.getElementById(id),view=$('maze-view'),canvas=$('maze-canvas'),ctx=canvas.getContext('2d');
 const hero=new Image(),wall=new Image();hero.onload=wall.onload=()=>active&&layout();hero.src='assets/qmap/hero-shadow-hunter.png';wall.src='assets/qmap/candy-block.png';
 let game=null,seed=Date.now()>>>0,active=false,difficulty='normal';
 const read=()=>{try{const s=JSON.parse(localStorage.getItem(key)||'null'),m=s?.maze,keyOf=p=>Array.isArray(p)&&p.length===2&&p.every(Number.isInteger)&&p[0]>=0&&p[0]<m.height&&p[1]>=0&&p[1]<m.width;if(!s||!['easy','normal','hard'].includes(s.difficulty)||!m||m.width!==31||m.height!==21||!Array.isArray(m.walls)||!Array.isArray(s.player)||!Array.isArray(s.enemies)||s.enemies.length>5||!Number.isInteger(s.moves)||s.moves<0||!keyOf(s.player)||!keyOf(m.start)||!keyOf(m.goal)||!s.enemies.every(keyOf)||!m.walls.every(k=>/^\d+,\d+$/.test(k)))return null;return s;}catch{return null;}};
 function save(){if(!game)return;try{localStorage.setItem(key,JSON.stringify({maze:game.maze,player:game.player,enemies:game.enemies,difficulty:game.difficulty,mode:game.mode,fog:game.fog,won:game.won,lost:game.lost,moves:game.moves,message:game.message}));$('maze-resume-title').classList.remove('hidden');}catch{}}
 function layout(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const w=Math.round(r.width*dpr),h=Math.round(r.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}ctx.setTransform(dpr,0,0,dpr,0,0);draw(r.width,r.height);}
 function sprite(image,x,y,size){if(image.complete&&image.naturalWidth)ctx.drawImage(image,x-size/2,y-size*.82,size,size);}
 function draw(width,height){if(!game)return;const m=game.maze,cell=Math.min((width-48)/m.width,(height-200)/m.height),mw=cell*m.width,mh=cell*m.height,left=(width-mw)/2,top=Math.max(88,(height-mh-100)/2+12),wallSet=new Set(m.walls),enemies=new Set(game.enemies.map(p=>p.join(','))),px=game.player;
  ctx.clearRect(0,0,width,height);ctx.fillStyle='#0b1417';ctx.fillRect(0,0,width,height);
  const fogRadius=game.fog?3:Infinity;
  for(let y=0;y<m.height;y++)for(let x=0;x<m.width;x++){const dx=Math.abs(y-px[0]),dy=Math.abs(x-px[1]),visible=Math.max(dx,dy)<=fogRadius;if(!visible)continue;const x0=left+x*cell,y0=top+y*cell,key=y+','+x;
   if(wallSet.has(key)){ctx.fillStyle='#192326';ctx.fillRect(x0,y0,cell,cell);if(cell>10)sprite(wall,x0+cell/2,y0+cell*.9,cell*.9);ctx.strokeStyle='#8ba69a26';ctx.lineWidth=1;ctx.strokeRect(x0+.5,y0+.5,cell-1,cell-1);}
   else{ctx.fillStyle=(x+y)%2?'#dce5d9':'#e8eee3';ctx.fillRect(x0,y0,cell,cell);ctx.strokeStyle='#82928522';ctx.strokeRect(x0+.5,y0+.5,cell-1,cell-1);}
   if(y===m.goal[0]&&x===m.goal[1]){ctx.fillStyle='#447ca8';ctx.fillRect(x0,y0,cell,cell);ctx.fillStyle='#f3f7e8';ctx.font=`700 ${Math.max(10,cell*.64)}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('E',x0+cell/2,y0+cell/2);}
   if(enemies.has(key)){ctx.fillStyle='#b54a42';ctx.fillRect(x0+cell*.13,y0+cell*.13,cell*.74,cell*.74);ctx.strokeStyle='#fff1e3';ctx.lineWidth=Math.max(1,cell*.055);ctx.strokeRect(x0+cell*.13,y0+cell*.13,cell*.74,cell*.74);ctx.fillStyle='#fff4e8';ctx.font=`700 ${Math.max(9,cell*.56)}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('M',x0+cell/2,y0+cell/2);}
  }
  const playerKey=game.player.join(',');if(Math.max(Math.abs(game.player[0]-px[0]),Math.abs(game.player[1]-px[1]))<=fogRadius){const x=left+px[1]*cell+cell/2,y=top+px[0]*cell+cell*.86;sprite(hero,x,y,cell*.96);if(!(hero.complete&&hero.naturalWidth)){ctx.fillStyle='#347c54';ctx.beginPath();ctx.arc(x,y-cell*.34,cell*.3,0,Math.PI*2);ctx.fill();}}
  $('maze-state').textContent=game.won?'出口已抵达':game.lost?'追猎失败':game.message;$('maze-count').textContent=`追击者 ${game.enemies.length} · ${({easy:'宽容',normal:'标准',hard:'凶险'})[game.difficulty]}`;$('maze-moves').textContent=`步数 ${game.moves}`;$('maze-fog').textContent=`迷雾：${game.fog?'开启':'关闭'}`;$('maze-mode').textContent=game.mode==='step'?'单步':'滑行';
  const done=game.won||game.lost;$('maze-result').classList.toggle('hidden',!done);$('maze-result').innerHTML=done?`<strong>${game.won?'你找到了出口':'追击者拦住了去路'}</strong><span>${game.won?`完成于 ${game.moves} 步`:'重新规划路线，再试一次。'}</span><div><button id="maze-result-restart">重开本图</button><button id="maze-result-new">生成新图</button></div>`:'';
  if(done){$('maze-result-restart').onclick=restart;$('maze-result-new').onclick=newMap;}
 }
 function begin(saved){if(active)return;active=true;document.body.classList.add('is-maze');$('intro').classList.add('hidden');$('game').classList.add('hidden');$('feedback-canvas').classList.add('hidden');document.querySelector('.scene-top').classList.add('hidden');document.querySelector('.player-hud').classList.add('hidden');document.querySelector('.arena-stamp').classList.add('hidden');$('world-hud').classList.add('hidden');$('world-interact').classList.add('hidden');$('field-kit').classList.add('hidden');$('boss-hud').classList.add('hidden');$('mission-hud').classList.add('hidden');$('q-activity-hud').classList.add('hidden');$('journey-status').classList.add('hidden');document.querySelector('.combat-bar').classList.add('hidden');document.querySelector('.build-panel').classList.add('hidden');view.classList.remove('hidden');game=saved||rules.state(rules.generate(31,21,2,seed),difficulty);difficulty=game.difficulty;view.focus?.();layout();save();}
 function finish(){active=false;document.body.classList.remove('is-maze');view.classList.add('hidden');$('game').classList.remove('hidden');$('feedback-canvas').classList.remove('hidden');document.querySelector('.scene-top').classList.remove('hidden');document.querySelector('.player-hud').classList.remove('hidden');document.querySelector('.arena-stamp').classList.remove('hidden');document.querySelector('.combat-bar').classList.remove('hidden');document.querySelector('.build-panel').classList.remove('hidden');window.shadowHunter?.returnTitle?.();}
 function move(key){if(!active)return;const d=rules.directions[key];if(!d)return;rules.move(game,d);save();layout();}
 function restart(){if(!game)return;game=rules.state(game.maze,difficulty);save();layout();}
 function newMap(){if(!game)return;seed=(Math.random()*0xffffffff)>>>0;game=rules.state(rules.generate(31,21,game.maze.density,seed,game.maze.enemies.length),difficulty);save();layout();}
 function resume(){const s=read();if(s){game=s;difficulty=s.difficulty;}begin(game);}
 function choose(){const saved=read();const panel=document.createElement('div');panel.className='maze-menu';panel.innerHTML=`<div class="modal-eyebrow">THIRD JOURNEY / GRID HUNT</div><h2>迷雾迷宫</h2><p>找到蓝色出口。每次移动后追击者都会沿最短路线靠近。</p><div class="maze-difficulties" role="group" aria-label="迷宫难度"><button data-difficulty="easy" aria-pressed="false"><b>宽容</b><small>1 名追击者 · 通道较宽</small></button><button data-difficulty="normal" aria-pressed="true"><b>标准</b><small>3 名追击者 · 标准密度</small></button><button data-difficulty="hard" aria-pressed="false"><b>凶险</b><small>5 名追击者 · 敌人每回合走两格</small></button></div><div class="maze-menu-actions"><button id="maze-start">开始迷宫 ↗</button>${saved?'<button id="maze-resume">继续上次进度</button>':''}<button id="maze-cancel">返回</button></div>`;
  $('modal-card').replaceChildren(panel);$('modal').classList.remove('hidden');$('modal').dataset.kind='mazeMenu';panel.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.difficulty;panel.querySelectorAll('[data-difficulty]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));});$('maze-start').onclick=()=>{const config={easy:[1,1],normal:[3,2],hard:[5,3]}[difficulty];game=rules.state(rules.generate(31,21,config[1],(Math.random()*0xffffffff)>>>0,config[0]),difficulty);$('modal').classList.add('hidden');begin(game);};if($('maze-resume'))$('maze-resume').onclick=()=>{$('modal').classList.add('hidden');resume();};$('maze-cancel').onclick=()=>{$('modal').classList.add('hidden');$('intro').classList.remove('hidden');};
 }
 $('maze-entry').addEventListener('click',choose);$('maze-exit').onclick=finish;$('maze-home').onclick=finish;$('maze-restart').onclick=restart;$('maze-new').onclick=newMap;$('maze-mode').onclick=()=>{if(game){game.mode=game.mode==='step'?'slide':'step';save();layout();}};$('maze-fog').onclick=()=>{if(game){game.fog=!game.fog;save();layout();}};
 for(const [id,keyName] of [['maze-left','ArrowLeft'],['maze-down','ArrowDown'],['maze-up','ArrowUp'],['maze-right','ArrowRight']])$(id).addEventListener('click',()=>move(keyName));
 window.addEventListener('keydown',e=>{if(!active)return;const key=e.code.startsWith('Key')?e.code.slice(3).toLowerCase():e.code;if(rules.directions[key]){e.preventDefault();e.stopImmediatePropagation();move(key);}else if(['KeyT','KeyF','KeyR','KeyN','Escape'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();if(e.code==='KeyT')$('maze-mode').click();if(e.code==='KeyF')$('maze-fog').click();if(e.code==='KeyR')restart();if(e.code==='KeyN')newMap();if(e.code==='Escape')finish();}},true);
 $('maze-resume-title').addEventListener('click',resume);new ResizeObserver(layout).observe(canvas);window.addEventListener('resize',layout);window.HUNTER_MAZE_ADVENTURE={active:()=>active,begin,resume,choose,finish,hasSave:()=>!!read()};
})();
